// ── Component: DeleteConfirmDialog ───────────────────────────────────────────
//
// Opens the native <dialog> as a modal and restores focus to the last-used
// trigger on close. Focus on open goes to the Cancel button (safe default)
// so the destructive Delete action requires deliberate navigation.

(function DeleteConfirmDialog() {
  const dialog     = document.getElementById('delete-dialog');
  const triggers   = document.querySelectorAll('.trigger');
  const cancelBtn  = dialog.querySelector('[data-action="cancel"]');
  const confirmBtn = dialog.querySelector('[data-action="confirm"]');

  // Track which trigger opened the dialog so we can restore focus to it.
  let lastTrigger = null;

  // ── Open ─────────────────────────────────────────────────────────────────
  triggers.forEach(trigger => {
    trigger.addEventListener('click', () => {
      lastTrigger = trigger;
      dialog.showModal();
      // Move focus to Cancel (not Delete) so the destructive action
      // is never the default keyboard target.
      cancelBtn.focus();
    });
  });

  // ── Close via Cancel ─────────────────────────────────────────────────────
  cancelBtn.addEventListener('click', () => dialog.close('cancel'));

  // ── Close via Confirm (destructive) ──────────────────────────────────────
  confirmBtn.addEventListener('click', () => {
    // In a real app: call the delete API here, then handle the result.
    dialog.close('delete');
  });

  // ── After close ──────────────────────────────────────────────────────────
  // The browser automatically returns focus to the element that opened the
  // dialog. We also restore it manually in case the trigger was removed.
  dialog.addEventListener('close', () => {
    if (dialog.returnValue === 'delete') {
      // Placeholder: show a success state or navigate away.
      console.log('Image deleted.');
    }
    if (lastTrigger && document.contains(lastTrigger)) {
      lastTrigger.focus();
    }
    lastTrigger = null;
  });
})();

