*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #f1f5f9;
  --color-surface:     #ffffff;
  --color-border:      #e2e8f0;
  --color-text:        #0f172a;
  --color-text-muted:  #575f6e;
  --color-primary:     #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-danger:      #c41a1a;
  --color-danger-hover:#b91c1c;
  --color-danger-bg:   #fef2f2;
  --color-danger-border:#fecaca;
  --color-tag-bg:      #eff6ff;
  --color-tag-text:    #1d4ed8;
  --radius-sm:         6px;
  --radius-md:         10px;
  --radius-lg:         16px;
  --shadow-card:       0 1px 3px rgba(0,0,0,.08), 0 4px 16px rgba(0,0,0,.06);
  --shadow-dialog:     0 20px 60px rgba(0,0,0,.22), 0 4px 16px rgba(0,0,0,.1);
  --transition:        .18s ease;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

html { font-size: 16px; }

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  line-height: 1.5;
}

/* ── Skip link ──────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Focus ring (visible for keyboard, invisible for pointer) */
:focus-visible {
  outline: 2.5px solid var(--color-primary);
  outline-offset: 2px;
}
:focus:not(:focus-visible) { outline: none; }

/* ── Site header ────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--color-text);
  text-decoration: none;
  letter-spacing: -.02em;
}
.logo svg { color: var(--color-primary); }

.site-nav { display: flex; align-items: center; gap: .25rem; }

.nav-link {
  padding: .375rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  color: var(--color-text-muted);
  text-decoration: none;
  font-weight: 500;
  transition: background var(--transition), color var(--transition);
}
.nav-link:hover { background: var(--color-bg); color: var(--color-text); }
.nav-link[aria-current="page"] { background: #eff6ff; color: var(--color-primary); }

.header-actions { margin-left: auto; display: flex; align-items: center; gap: .75rem; }

.avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #2563eb);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  cursor: pointer;
  border: none;
}

/* ── Main content ───────────────────────────────────────── */
.main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

/* ── Breadcrumb ─────────────────────────────────────────── */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: .375rem;
  margin-bottom: 1.5rem;
  font-size: .8125rem;
  color: var(--color-text-muted);
}
.breadcrumb a {
  color: var(--color-text-muted);
  text-decoration: none;
  font-weight: 500;
}
.breadcrumb a:hover { color: var(--color-primary); text-decoration: underline; }
.breadcrumb-sep { color: var(--color-border); }
.breadcrumb [aria-current="page"] { color: var(--color-text); font-weight: 500; }

/* ── Page heading ───────────────────────────────────────── */
.page-heading {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.025em;
  margin-bottom: 1.5rem;
  color: var(--color-text);
}

/* ── Preview layout ─────────────────────────────────────── */
.preview-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 1.5rem;
  align-items: start;
}

@media (max-width: 820px) {
  .preview-layout { grid-template-columns: 1fr; }
}

/* ── Image card ─────────────────────────────────────────── */
.image-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.image-stage {
  position: relative;
  background: #0f172a;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  /* inline placeholder gradient */
  background: linear-gradient(135deg,
    #1e3a5f 0%,
    #264d7a 20%,
    #1a5c4a 40%,
    #2d7a3e 55%,
    #4a8c5c 70%,
    #2e6b8a 85%,
    #1a3f6f 100%);
}

.image-badge {
  position: absolute;
  top: .75rem;
  right: .75rem;
  background: rgba(0,0,0,.55);
  backdrop-filter: blur(8px);
  color: #fff;
  font-size: .7rem;
  font-weight: 600;
  padding: .25rem .6rem;
  border-radius: 100px;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.image-card-footer {
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  flex-wrap: wrap;
}

.image-filename {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-meta-small {
  font-size: .75rem;
  color: var(--color-text-muted);
  margin-top: .125rem;
}

/* ── Action buttons under image ─────────────────────────── */
.image-actions {
  display: flex;
  gap: .625rem;
  align-items: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .5rem .875rem;
  border-radius: var(--radius-sm);
  font-size: .8125rem;
  font-weight: 600;
  line-height: 1;
  cursor: pointer;
  border: 1px solid transparent;
  text-decoration: none;
  transition: background var(--transition), border-color var(--transition), color var(--transition), box-shadow var(--transition);
}
.btn svg { flex-shrink: 0; }

.btn-primary {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}
.btn-primary:hover { background: var(--color-primary-hover); border-color: var(--color-primary-hover); }

.btn-secondary {
  background: var(--color-surface);
  color: var(--color-text);
  border-color: var(--color-border);
}
.btn-secondary:hover { background: var(--color-bg); }

.btn-danger-outline {
  background: var(--color-surface);
  color: var(--color-danger);
  border-color: var(--color-danger-border);
}
.btn-danger-outline:hover {
  background: var(--color-danger-bg);
  border-color: #fca5a5;
}

.btn-danger-solid {
  background: var(--color-danger);
  color: #fff;
  border-color: var(--color-danger);
}
.btn-danger-solid:hover { background: var(--color-danger-hover); border-color: var(--color-danger-hover); }

/* ── Details panel ──────────────────────────────────────── */
.details-panel {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.panel-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.panel-header {
  padding: .875rem 1.125rem;
  border-bottom: 1px solid var(--color-border);
  font-size: .8125rem;
  font-weight: 700;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: .06em;
}

.meta-list {
  padding: .5rem 0;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: .5rem 1.125rem;
  font-size: .8125rem;
  gap: 1rem;
}
.meta-row:not(:last-child) { border-bottom: 1px solid var(--color-border); }

.meta-label { color: var(--color-text-muted); font-weight: 500; white-space: nowrap; }
.meta-value { color: var(--color-text); font-weight: 600; text-align: right; }

/* ── Tags ───────────────────────────────────────────────── */
.tags-area { padding: .875rem 1.125rem; display: flex; flex-wrap: wrap; gap: .375rem; }

.tag {
  background: var(--color-tag-bg);
  color: var(--color-tag-text);
  font-size: .75rem;
  font-weight: 600;
  padding: .25rem .625rem;
  border-radius: 100px;
}

/* ── Panel actions ──────────────────────────────────────── */
.panel-actions {
  padding: .875rem 1.125rem;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}
.panel-actions .btn { width: 100%; justify-content: center; padding: .625rem 1rem; font-size: .875rem; }

/* ── Danger zone card ───────────────────────────────────── */
.danger-zone-card {
  background: var(--color-danger-bg);
  border-color: var(--color-danger-border);
}
.danger-zone-card .panel-header {
  background: var(--color-danger-bg);
  border-bottom-color: var(--color-danger-border);
  color: var(--color-danger);
}
.danger-zone-card .panel-actions { padding: .875rem 1.125rem; }

/* ── ARIA dialog backdrop ────────────────────────────────── */
#dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, .55);
  backdrop-filter: blur(4px);
  z-index: 200;
}
#dialog-backdrop[hidden] { display: none; }

/* ── ARIA dialog container ───────────────────────────────── */
#delete-dialog {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 201;
  pointer-events: none; /* let backdrop receive clicks */
}
#delete-dialog[hidden] { display: none; }

.dialog-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-danger-bg);
  border: 1px solid var(--color-danger-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-danger);
  margin-bottom: 1.25rem;
}

.dialog-heading {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -.02em;
  margin-bottom: .5rem;
}

.dialog-body {
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

.dialog-body strong { color: var(--color-text); font-weight: 600; }

.dialog-footer {
  display: flex;
  gap: .75rem;
  justify-content: flex-end;
}

.dialog-footer .btn { padding: .625rem 1.25rem; font-size: .875rem; }

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .dialog-inner { animation: none; }
  *, *::before, *::after { transition-duration: .01ms !important; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn { forced-color-adjust: auto; }
  dialog::backdrop { background: Canvas; opacity: .85; }
}
