//
// ARIA alertdialog implementation (div-based, not native <dialog>) so that
// automated contrast checkers (axe-core) are not confused by Chromium's
// top-layer ::backdrop compositing.
//
// Focus management:
//   • Open  → Cancel button (never the destructive action)
//   • Close → restored to whichever .trigger opened the dialog
//
// Background inertness:
//   • All siblings of the dialog/backdrop receive `inert` while open.
//   • The `inert` attribute causes the browser to suppress Tab navigation
//     out of the dialog without a manual focus-trap loop.
//
// Keyboard:
//   • Escape closes the dialog (keydown listener on document while open).

(function DeleteConfirmDialog() {
  const dialog   = document.getElementById('delete-dialog');
  const triggers = document.querySelectorAll('.trigger');
  const cancelBtn  = dialog.querySelector('[data-action="cancel"]');
  const confirmBtn = dialog.querySelector('[data-action="confirm"]');

  // Siblings of the dialog and backdrop in <body> — made inert while open.
  // Collect once; filter out the dialog and backdrop themselves.
  const pageSiblings = () =>
    Array.from(document.body.children).filter(
      el => el !== dialog && el !== backdrop
    );

  let lastTrigger = null;

  // ── openDialog() ─────────────────────────────────────────────────────────
  function openDialog(trigger) {
    lastTrigger = trigger;

    // Show dialog and backdrop
    dialog.removeAttribute('hidden');
    backdrop.removeAttribute('hidden');

    // Make all page content inert (browser traps focus inside dialog)
    pageSiblings().forEach(el => el.setAttribute('inert', ''));

    // Move focus to Cancel — never the destructive action
    cancelBtn.focus();
  }

  // ── closeDialog() ────────────────────────────────────────────────────────
  function closeDialog(returnValue) {
    dialog.setAttribute('hidden', '');
    backdrop.setAttribute('hidden', '');

    // Restore page interactivity
    pageSiblings().forEach(el => el.removeAttribute('inert'));

    if (returnValue === 'delete') {
      // In a real app: call the delete API here, then navigate / show toast.
      console.log('Image deleted.');
    }

    // Restore focus to the element that opened the dialog
    if (lastTrigger && document.contains(lastTrigger)) {
      lastTrigger.focus();
    }
    lastTrigger = null;
  }

  // ── Wire up triggers ──────────────────────────────────────────────────────
  triggers.forEach(trigger => {
    trigger.addEventListener('click', () => openDialog(trigger));
  });

  cancelBtn.addEventListener('click',  () => closeDialog('cancel'));
  confirmBtn.addEventListener('click', () => closeDialog('delete'));

  // ── Escape key ────────────────────────────────────────────────────────────
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && !dialog.hasAttribute('hidden')) {
      closeDialog('cancel');
    }
  });
})();
